27	/**
28	 * This class represents a key that uniquely identifies (on a logical level) state handles for
29	 * registration in the {@link SharedStateRegistry}. Two files which should logically be the same
30	 * should have the same {@link SharedStateRegistryKey}. The meaning of logical equivalence is up to
31	 * the application.
32	 */
33	public class SharedStateRegistryKey extends StringBasedID {
34	
35	    private static final long serialVersionUID = 1L;
36	
37	    public SharedStateRegistryKey(String prefix, StateHandleID stateHandleID) {
38	        super(prefix + '-' + stateHandleID);
39	    }
40	
41	    @VisibleForTesting
42	    public SharedStateRegistryKey(String keyString) {
43	        super(keyString);
44	    }
45	
46	    /** Create a unique key based on physical id. */
47	    public static SharedStateRegistryKey forStreamStateHandle(StreamStateHandle handle) {
48	        String keyString = handle.getStreamStateHandleID().getKeyString();
49	        // key strings tend to be longer, so we use the MD5 of the key string to save memory
50	        return new SharedStateRegistryKey(
51	                UUID.nameUUIDFromBytes(keyString.getBytes(StandardCharsets.UTF_8)).toString());
52	    }
53	}
